import{_ as l,o as a,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2021-07-15","description":"","frontmatter":{"title":"Ceph Performance Meeting 2021-07-15","date":"2021-07-15T00:00:00.000Z","updated":"2021-08-24T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","CRUSH算法","高可用性","可伸缩性"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Performance_Meeting_2021-07-15.md","filePath":"posts/2021/Ceph_Performance_Meeting_2021-07-15.md","lastUpdated":1780460162000}'),t={name:"posts/2021/Ceph_Performance_Meeting_2021-07-15.md"};function o(n,e,s,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h3 id="改进后的总结" tabindex="-1">改进后的总结 <a class="header-anchor" href="#改进后的总结" aria-label="Permalink to &quot;改进后的总结&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期</strong>: 2021年7月15日</li><li><strong>参与者</strong>: Orlando, Mark, 以及其他未明确提及的开发人员。</li><li><strong>主要议题</strong>: 讨论了Ceph项目的多个技术问题，包括持久性RBD缓存、CephFS性能优化、IBM研究人员的贡献、以及Crimson存储引擎的性能问题。</li></ul><h4 id="讨论的主要议题" tabindex="-1">讨论的主要议题 <a class="header-anchor" href="#讨论的主要议题" aria-label="Permalink to &quot;讨论的主要议题&quot;">​</a></h4><ol><li><p><strong>持久性RBD缓存</strong>:</p><ul><li>Orlando的同事在测试持久性RBD缓存时遇到了性能问题。</li><li>使用GDB和pmp工具进行调试，发现与工作线程池的繁忙状态有关。</li><li>测试包括fio、rbd bench和自定义Python程序，结果显示性能不如预期。</li></ul></li><li><p><strong>CephFS性能优化</strong>:</p><ul><li>Orlando正在与Dennis Nujab合作，优化CephFS的整体性能。</li><li>探讨了Octane SSD和持久内存的使用，以及IO 500测试的结果。</li></ul></li><li><p><strong>IBM研究人员的贡献</strong>:</p><ul><li>一位IBM研究人员提交了多个关于内存分配优化和避免内存复制的Pull Request (PR)。</li><li>这些PR主要集中在librbd，但也涉及其他部分。</li></ul></li><li><p><strong>Crimson存储引擎</strong>:</p><ul><li>讨论了Crimson的性能问题，特别是与Blue Store的比较。</li><li>发现Crimson在某些情况下性能不如预期，主要瓶颈在于reactor线程。</li></ul></li></ol><h4 id="决定的事项" tabindex="-1">决定的事项 <a class="header-anchor" href="#决定的事项" aria-label="Permalink to &quot;决定的事项&quot;">​</a></h4><ul><li>需要进一步分析和优化持久性RBD缓存的性能问题。</li><li>继续进行CephFS的性能优化工作，特别是与Octane SSD和持久内存的结合使用。</li><li>审查并可能合并IBM研究人员的PR，以提升Ceph的整体性能。</li><li>对于Crimson存储引擎，需要进一步的工作来解决reactor线程的瓶颈问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>持续进行性能测试和调试，解决持久性RBD缓存的问题。</li><li>完成CephFS的性能优化工作，并在实际环境中进行更多测试。</li><li>审查IBM研究人员的PR，并与他们合作确保代码的质量和性能。</li><li>对Crimson存储引擎进行进一步的研究和开发，特别是关于多reactor的支持和优化。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议中还提到了一些具体的PR和代码变更，但这些细节主要涉及技术实现，未在此纪要中详细列出。</li></ul><h3 id="结束语" tabindex="-1">结束语 <a class="header-anchor" href="#结束语" aria-label="Permalink to &quot;结束语&quot;">​</a></h3><p>会议在讨论了各项议题后结束，参与者计划继续各自的工作，并在未来的会议中更新进展。会议结束时，大家互相道别，并期待下周的再次会面。</p>',13)])])}const _=l(t,[["render",o]]);export{c as __pageData,_ as default};
